import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { DEFAULT_CONFIG } from '../src/config.js';
import { loadReplayDataset } from '../src/historical-simulator.js';
import { confirmedRetestReclaimV2, cyclePatternSimilarityEngine } from '../src/strategy-lab-v2.js';
import { mean } from '../src/math.js';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const finite=v=>Number.isFinite(Number(v)),round=(v,d=3)=>finite(v)?Number(Number(v).toFixed(d)):null,avg=xs=>xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null;
const upper=(rows,date)=>{let lo=0,hi=rows.length;while(lo<hi){const m=(lo+hi)>>1;if(rows[m].date<=date)lo=m+1;else hi=m;}return lo;};
const wilson=(k,n,z=1.96)=>{if(!n)return null;const p=k/n,z2=z*z,den=1+z2/n;return Math.max(0,(p+z2/(2*n)-z*Math.sqrt((p*(1-p)+z2/(4*n))/n))/den)*100;};
function sharedDates(ds,min){const c=new Map();for(const rows of ds.histories.values())for(const b of rows)c.set(b.date,(c.get(b.date)||0)+1);return [...c].filter(([,n])=>n>=min).map(([d])=>d).sort();}
function turnoverOkay(rows){const x=rows.slice(-20).map(b=>Number(b.close)*Number(b.volume)).filter(Number.isFinite);return x.length>=12&&(mean(x)??0)>=750000;}
function trendOkay(rows){if(rows.length<55)return false;const c=rows.map(x=>Number(x.close)),m20=mean(c.slice(-20)),m50=mean(c.slice(-50));return finite(m20)&&finite(m50)&&c.at(-1)>=m20*.97&&m20>=m50*.98;}
function marketContext(rows,date){const x=rows.slice(0,upper(rows,date));if(x.length<55)return {regime:'UNKNOWN',return20Pct:null};const c=x.map(v=>Number(v.close)),last=c.at(-1),m50=mean(c.slice(-50)),m200=x.length>=200?mean(c.slice(-200)):null,r20=c.length>20&&c.at(-21)>0?(last/c.at(-21)-1)*100:null;let regime='NEUTRAL';if(finite(m200)&&last<m200*.98)regime='BEAR';else if(finite(m200)&&last>m50&&m50>m200)regime='BULL';else if(last<m50)regime='CAUTION';return {regime,return20Pct:round(r20,2)};}
function fill(bar,lo,hi){if(bar.open>=lo&&bar.open<=hi)return bar.open;if(bar.open>hi&&bar.low<=hi)return hi;if(bar.open<lo)return null;if(bar.low<=hi&&bar.high>=lo)return hi;return null;}
function retestBase(row,date){const raw=row.retest.raw,p=raw?.plan||{},z=p.entryZone||{};return {symbol:row.symbol,signalDate:date,selectionRank:row.selectionRank??null,marketRegime:row.market?.regime??'UNKNOWN',benchmark20dPct:row.market?.return20Pct??null,retestScore:row.retest.score,cycleScore:row.cycle?.score??null,cyclePass:Boolean(row.cycle?.pass),cycleSamples:row.cycle?.raw?.samples??null,cycleWeightedHitPct:row.cycle?.raw?.similarityWeightedHitPct??null,touches:raw?.touches??null,breakoutVolumeRatio:raw?.breakout?.volumeRatio??null,breakoutClosePositionPct:raw?.breakout?.closePositionPct??null,breakoutBodyAtr:raw?.breakout?.bodyAtr??null,retestDepthAtr:raw?.retest?.depthAtr??null,retestVolumeVsBreakout:raw?.retest?.volumeVsBreakout??null,retestVolumeVsBase:raw?.retest?.volumeVsBase??null,reclaimVolumeRatio:raw?.reclaim?.volumeRatio??null,reclaimSignalAgeSessions:raw?.reclaim?.signalAgeSessions??null,entryLow:round(Number(z.from),4),entryHigh:round(Number(z.to),4),referenceEntry:p.referenceEntry??null,stopLoss:round(Number(p.stopLoss),4),target:round(Number(p.precisionTarget?.price),4),riskPct:p.riskPct??null};}
function evalRetest(row,full,date,{expiry=3,hold=10,cost=.6}={}){const b=retestBase(row,date),lo=Number(b.entryLow),hi=Number(b.entryHigh),stop=Number(b.stopLoss),target=Number(b.target);if(![lo,hi,stop,target].every(Number.isFinite)||!(hi>=lo&&lo>stop&&target>hi))return {...b,entered:false,outcome:'INVALID_PLAN'};const si=upper(full,date)-1;if(si<0)return {...b,entered:false,outcome:'NO_SIGNAL_BAR'};let e=null;for(let j=si+1;j<=Math.min(full.length-1,si+expiry);j++){const p=fill(full[j],lo,hi);if(p!=null){e={i:j,p,date:full[j].date};break;}}if(!e)return {...b,entered:false,outcome:'EXPIRED'};const end=Math.min(full.length-1,e.i+hold-1);let oi=end,px=full[end]?.close??e.p,outcome='TIME',hit=false,stopHit=false;for(let j=e.i;j<=end;j++){if(full[j].low<=stop){oi=j;px=stop;outcome='STOP';stopHit=true;break;}if(full[j].high>=target){oi=j;px=target;outcome='TARGET';hit=true;break;}}const risk=e.p-stop,costCash=e.p*cost/100;return {...b,entered:true,entryDate:e.date,entryPrice:round(e.p,4),actualRiskPct:round(risk/e.p*100,2),targetHit:hit,stopHit,outcome,exitDate:full[oi]?.date??null,holdingSessions:oi-e.i+1,netPct:round((px-e.p)/e.p*100-cost,3),netR:round(risk>0?(px-e.p-costCash)/risk:null,3)};}
function evalCycle(row,full,date,{horizon=15,cost=.6}={}){const raw=row.cycle.raw||{},def=raw.launchDefinition||{},tp=Number(def.targetPct??6),sp=Number(def.stopPct??4),si=upper(full,date)-1,b={symbol:row.symbol,signalDate:date,selectionRank:row.selectionRank??null,marketRegime:row.market?.regime??'UNKNOWN',benchmark20dPct:row.market?.return20Pct??null,cycleScore:row.cycle.score,samples:raw.samples??null,weightedHitPct:raw.similarityWeightedHitPct??null,wilson:raw.wilson95LowerHitPct??null,medianSimilarity:raw.medianSimilarity??null,currentCycleAge:raw.currentCycle?.ageSessions??null,cyclePhaseScore:raw.currentCycle?.phaseScore??null};if(si<0||si+1>=full.length)return {...b,entered:false,outcome:'NO_FUTURE'};const e=full[si+1],entry=Number(e.open||e.close);if(!(entry>0))return {...b,entered:false,outcome:'INVALID_ENTRY'};const target=entry*(1+tp/100),stop=entry*(1-sp/100),end=Math.min(full.length-1,si+horizon);let oi=end,px=full[end]?.close??entry,outcome='TIME',hit=false,stopHit=false;for(let j=si+1;j<=end;j++){if(full[j].low<=stop){oi=j;px=stop;outcome='STOP';stopHit=true;break;}if(full[j].high>=target){oi=j;px=target;outcome='TARGET';hit=true;break;}}const risk=entry-stop,costCash=entry*cost/100;return {...b,entered:true,entryDate:e.date,entryPrice:round(entry,4),stopLoss:round(stop,4),target:round(target,4),targetHit:hit,stopHit,outcome,exitDate:full[oi]?.date??null,holdingSessions:oi-si,netPct:round((px-entry)/entry*100-cost,3),netR:round(risk>0?(px-entry-costCash)/risk:null,3)};}
function deoverlap(rows){const x=[...rows].sort((a,b)=>String(a.signalDate).localeCompare(String(b.signalDate))||String(a.symbol).localeCompare(String(b.symbol))),active=new Map(),out=[];for(const t of x){const u=active.get(t.symbol);if(u&&String(t.signalDate)<=String(u))continue;out.push(t);active.set(t.symbol,t.exitDate||t.signalDate);}return out;}
function summary(rows){const e=deoverlap(rows.filter(x=>x.entered)),hits=e.filter(x=>x.targetHit),stops=e.filter(x=>x.stopHit&&!x.targetHit),wins=e.filter(x=>Number(x.netPct)>0),loss=e.filter(x=>Number(x.netPct)<0),gp=wins.reduce((s,x)=>s+Number(x.netPct),0),gl=Math.abs(loss.reduce((s,x)=>s+Number(x.netPct),0));return {selected:rows.length,entered:e.length,uniqueSymbols:new Set(e.map(x=>x.symbol)).size,targetHitPct:e.length?round(hits.length/e.length*100,1):null,wilson95LowerHitPct:e.length?round(wilson(hits.length,e.length),1):null,stopBeforeTargetPct:e.length?round(stops.length/e.length*100,1):null,positivePct:e.length?round(wins.length/e.length*100,1):null,averageNetPct:round(avg(e.map(x=>Number(x.netPct))),3),expectancyR:round(avg(e.map(x=>Number(x.netR)).filter(Number.isFinite)),3),profitFactor:gl?round(gp/gl,3):(gp>0?'INF':null)};}
function temporal(rows){const x=deoverlap(rows.filter(r=>r.entered)).sort((a,b)=>String(a.signalDate).localeCompare(String(b.signalDate))),m=Math.floor(x.length/2),years={};for(const r of x){const y=String(r.signalDate).slice(0,4);(years[y]??=[]).push(r);}for(const y of Object.keys(years))years[y]=summary(years[y]);return {firstHalf:summary(x.slice(0,m)),lastHalf:summary(x.slice(m)),byYear:years};}

const minUniverse=60,step=3,maxSignals=700,expiry=3,hold=10,cycleHorizon=15,ds=await loadReplayDataset({config:DEFAULT_CONFIG}),all=sharedDates(ds,minUniverse),eligible=all.filter(date=>{let mature=0,future=0;for(const rows of ds.histories.values()){const i=upper(rows,date)-1;if(i>=DEFAULT_CONFIG.market.requiredHistorySessions-1)mature++;if(i>=0&&rows.length-i-1>=expiry+cycleHorizon)future++;}return mature>=minUniverse&&future>=Math.min(minUniverse,mature);}),dates=eligible.filter((_,i)=>i%step===0).slice(-maxSignals),retestTrades=[],cycleTrades=[],ensembleTrades=[],signals=[];
for(let di=0;di<dates.length;di++){const date=dates[di];if(di%50===0)console.log(`STRATEGY_LAB_V2_REPLAY ${di+1}/${dates.length} ${date}`);const market=marketContext(ds.benchmark,date),candidates=[];for(const entry of ds.entries){const full=ds.histories.get(entry.ticker)||[],past=full.slice(0,upper(full,date));if(past.length<DEFAULT_CONFIG.market.requiredHistorySessions||!turnoverOkay(past)||!trendOkay(past))continue;const retest=confirmedRetestReclaimV2(past,DEFAULT_CONFIG),cycle=(retest.pass||di%2===0)?cyclePatternSimilarityEngine(past,DEFAULT_CONFIG):{pass:false,score:0,raw:{samples:0}};if(retest.pass||cycle.pass)candidates.push({symbol:entry.ticker,retest,cycle,full,market});}const rr=candidates.filter(x=>x.retest.pass).sort((a,b)=>(b.retest.score+(b.cycle.pass?b.cycle.score*.15:0))-(a.retest.score+(a.cycle.pass?a.cycle.score*.15:0))).slice(0,3).map((x,i)=>({...x,selectionRank:i+1})),cc=candidates.filter(x=>x.cycle.pass).sort((a,b)=>b.cycle.score-a.cycle.score).slice(0,3).map((x,i)=>({...x,selectionRank:i+1})),ee=candidates.filter(x=>x.retest.pass&&x.cycle.pass).sort((a,b)=>(b.retest.score+b.cycle.score)-(a.retest.score+a.cycle.score)).slice(0,3).map((x,i)=>({...x,selectionRank:i+1}));signals.push({date,market,retestCandidates:rr.map(x=>({symbol:x.symbol,rank:x.selectionRank,retestScore:x.retest.score,cycleScore:x.cycle.score,cyclePass:x.cycle.pass})),cycleCandidates:cc.map(x=>({symbol:x.symbol,rank:x.selectionRank,cycleScore:x.cycle.score,samples:x.cycle.raw?.samples,weightedHitPct:x.cycle.raw?.similarityWeightedHitPct})),ensembleCandidates:ee.map(x=>({symbol:x.symbol,rank:x.selectionRank,retestScore:x.retest.score,cycleScore:x.cycle.score}))});for(const x of rr)retestTrades.push(evalRetest(x,x.full,date,{expiry,hold}));for(const x of cc)cycleTrades.push(evalCycle(x,x.full,date,{horizon:cycleHorizon}));for(const x of ee)ensembleTrades.push(evalRetest(x,x.full,date,{expiry,hold}));}
const report={schemaVersion:'sepa-x-strategy-lab-v2-historical.2',engineId:DEFAULT_CONFIG.engineId,generatedAt:new Date().toISOString(),researchOnly:true,promotionAllowed:false,automaticEligibilityImpact:'NONE',methodology:{pointInTime:true,noLookahead:true,currentFundamentalsExcluded:true,currentCatalystsExcluded:true,signalFrequency:`every ${step} common sessions`,maxSignalDates:maxSignals,selection:'top 3 per challenger; liquidity/trend guard; no core eligibility impact',sameBarAmbiguity:'STOP_FIRST',roundTripCostPct:.6,retestTarget:'planned P1 = 0.8R from RETEST_RECLAIM_V2 geometry',cycleTarget:'6% launch before 4% failure stop within 15 sessions',mechanicalFeaturesPersisted:true},dataset:{symbolsRequested:ds.requested,symbolsLoaded:ds.loaded,historyErrors:ds.errors.length,commonDates:all.length,eligibleSignalDates:eligible.length,signalDates:dates.length},results:{retestReclaimV2:{summary:summary(retestTrades),temporal:temporal(retestTrades)},cyclePatternSimilarity:{summary:summary(cycleTrades),temporal:temporal(cycleTrades)},ensemble:{summary:summary(ensembleTrades),temporal:temporal(ensembleTrades)}},promotionDecision:{eligible:false,reason:'CHALLENGER_ONLY_REQUIRES_WALK_FORWARD_FEATURE_VALIDATION'},signals,trades:{retestReclaimV2:retestTrades,cyclePatternSimilarity:cycleTrades,ensemble:ensembleTrades},errors:ds.errors};
fs.writeFileSync(path.join(root,'data/research/strategy-lab-v2-historical.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({dataset:report.dataset,retest:report.results.retestReclaimV2.summary,cycle:report.results.cyclePatternSimilarity.summary,ensemble:report.results.ensemble.summary},null,2));
